head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > renderType]<br/>Calendar 컴포넌트의 HTML 렌더링 방식을 설정합니다.",
    "validation" : [
        "미설정 시 기본값 'component' 로 동작하여 Calendar 내부를 div 및 table 태그를 사용한 WebSquare 컴포넌트 방식으로 렌더링합니다.",
        "component 설정 시 Calendar 내부를 div 및 table 태그를 사용한 WebSquare 컴포넌트 방식으로 렌더링합니다.",
        "native 설정 시 Calendar 내부의 SelectBox 가 'select' 태그로 렌더링됩니다.",
        "native 설정 시 날짜 및 버튼 요소가 'button' 태그로 렌더링됩니다.",
        "accessibility=true 이면 renderType 속성이 'native' 로 강제 설정됩니다.",        
        "setDisabled() 메소드는 renderType='native' 이면 select 요소에 disabled 속성을 직접 설정하고, 'component' 이면 SelectBox 의 setDisabled() 메소드를 호출합니다.",
        "renderType='native' 또는 displayDayType='textNative' 이면 요일 헤더가 'th' 태그로 렌더링됩니다.",        
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        renderType : con_renderType.getText(),
        accessibility : con_accessibility.getText(),
        displayDayType : con_displayDayType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// [component 전용] Calendar 내부에 div 및 table 태그 존재 여부 확인 (WebSquare 컴포넌트 방식)
scwin.getDivTableStructure = function () {
    let rt = target1.options.renderType;
    // validation: component → Calendar 내부를 div 및 table 태그를 사용한 WebSquare 컴포넌트 방식으로 렌더링
    // (native 는 div+table 구조가 동일하게 존재하므로 component 한정 검증)
    if (rt === 'native') return;

    let r = target1.render;
    let outerTag = r.tagName.toLowerCase();
    let innerTable = r.querySelector('table');
    let innerDiv = r.querySelector('div');
    wf_body_bottom.getObj("scwin").setReturnValue("[Calendar 내부 구조(div+table)] 최외곽 tag='" + outerTag + "', 내부 div 존재=" + (innerDiv ? 'O' : 'X') + ", 내부 table 존재=" + (innerTable ? 'O (태그=' + innerTable.tagName.toLowerCase() + ')' : 'X'));
}



// [공통] 적용된 renderType 값 + accessibility=true 시 native 강제 적용 여부 표시
scwin.getAppliedRenderType = function () {
    let rt = target1.options.renderType;
    let acc = target1.options.accessibility;
    // validation: accessibility=true 이면 renderType 이 'native' 로 강제 설정됨
    let forced = (acc === true && rt === 'native') ? ' (accessibility=true → native 강제 적용)' : '';
    wf_body_bottom.getObj("scwin").setReturnValue("[적용된 renderType] '" + rt + "'" + forced);
}



// [공통] year/month SelectBox 렌더링 태그 — native=select, component=div
scwin.getSelectBoxRenderTag = function () {
    let yearEl = target1.render.querySelector("[class*='w2calendar_selectbox_year']");
    let monthEl = target1.render.querySelector("[class*='w2calendar_selectbox_month']");

    let yearTag = yearEl ? yearEl.tagName.toLowerCase() : '없음';
    let monthTag = monthEl ? monthEl.tagName.toLowerCase() : '없음';

    // validation: native → SelectBox 가 select 태그 / component → div 태그 (WebSquare SelectBox)
    wf_body_bottom.getObj("scwin").setReturnValue("[SelectBox 렌더링 태그] year='" + yearTag + "', month='" + monthTag + "'");
}



// [공통] 헤더 이전/다음 버튼 태그 — native=button, component=div
scwin.getHeaderButtonTag = function () {
    let lastYearEl = target1.render.querySelector("[class*='w2calendar_header_last_year']");
    let lastMonthEl = target1.render.querySelector("[class*='w2calendar_header_last_month']");
    let nextMonthEl = target1.render.querySelector("[class*='w2calendar_header_next_month']");
    let nextYearEl = target1.render.querySelector("[class*='w2calendar_header_next_year']");

    let lastYearTag = lastYearEl ? lastYearEl.tagName.toLowerCase() : '없음';
    let lastMonthTag = lastMonthEl ? lastMonthEl.tagName.toLowerCase() : '없음';
    let nextMonthTag = nextMonthEl ? nextMonthEl.tagName.toLowerCase() : '없음';
    let nextYearTag = nextYearEl ? nextYearEl.tagName.toLowerCase() : '없음';

    // validation: native → 날짜/버튼 요소가 button 태그 / component → div 태그
    wf_body_bottom.getObj("scwin").setReturnValue("[헤더 버튼 태그] last_year='" + lastYearTag + "', last_month='" + lastMonthTag + "', next_month='" + nextMonthTag + "', next_year='" + nextYearTag + "'");
}



// [공통] 요일 헤더 셀 태그 — native 또는 displayDayType=textNative 이면 'th', 그 외 'td'(component 모드)
scwin.getWeekHeaderTag = function () {
    let firstCell = target1.render.querySelector("thead tr > *");
    if (!firstCell) {
        wf_body_bottom.getObj("scwin").setReturnValue("[요일 헤더 셀 태그] thead 없음");
        return;
    }
    let cellTag = firstCell.tagName.toLowerCase();
    let rt = target1.options.renderType;
    let ddt = target1.options.displayDayType;

    // validation: renderType='native' 또는 displayDayType='textNative' 이면 요일 헤더가 th 태그로 렌더링
    wf_body_bottom.getObj("scwin").setReturnValue("[요일 헤더 셀 태그] '" + cellTag + "' (renderType='" + rt + "', displayDayType='" + ddt + "')");
}



// [속성/DOM 정보 조회] 버튼 — 위 검증 항목을 모두 출력
scwin.btn_getInfo_onclick = function (e) {
    scwin.getAppliedRenderType();
    scwin.getDivTableStructure();
    scwin.getSelectBoxRenderTag();
    scwin.getHeaderButtonTag();
    scwin.getWeekHeaderTag();
}



// [setDisabled(true) 호출] 버튼 — renderType 별 처리 방식 차이 확인
scwin.btn_setDisabledTrue_onclick = function (e) {
    target1.setDisabled(true);

    let rt = target1.options.renderType;
    // year/month SelectBox 요소 조회
    let yearEl = target1.render.querySelector("[class*='w2calendar_selectbox_year']");
    let monthEl = target1.render.querySelector("[class*='w2calendar_selectbox_month']");

    // validation: setDisabled() 는 renderType='native' → select 요소에 disabled 속성 직접 설정
    //            renderType='component' → SelectBox 의 setDisabled() 메소드 호출
    if (rt === 'native') {
        let yearDisabledAttr = yearEl ? yearEl.getAttribute('disabled') : '없음';
        let monthDisabledAttr = monthEl ? monthEl.getAttribute('disabled') : '없음';
        wf_body_bottom.getObj("scwin").setReturnValue("[setDisabled(true) - native] select.disabled 속성 = year:'" + yearDisabledAttr + "', month:'" + monthDisabledAttr + "'");
    } else {
        let yearSb = target1.getChild(target1.id + "_selectbox_year");
        let monthSb = target1.getChild(target1.id + "_selectbox_month");
        let yearSbDisabled = yearSb ? yearSb.options.disabled : '없음';
        let monthSbDisabled = monthSb ? monthSb.options.disabled : '없음';
        wf_body_bottom.getObj("scwin").setReturnValue("[setDisabled(true) - component] SelectBox.options.disabled = year:" + yearSbDisabled + ", month:" + monthSbDisabled);
    }
}



// [setDisabled(false) 호출] 버튼 — 비활성화 해제
scwin.btn_setDisabledFalse_onclick = function (e) {
    target1.setDisabled(false);

    let rt = target1.options.renderType;
    let yearEl = target1.render.querySelector("[class*='w2calendar_selectbox_year']");
    let monthEl = target1.render.querySelector("[class*='w2calendar_selectbox_month']");

    if (rt === 'native') {
        let yearDisabledAttr = yearEl ? yearEl.getAttribute('disabled') : '없음';
        let monthDisabledAttr = monthEl ? monthEl.getAttribute('disabled') : '없음';
        wf_body_bottom.getObj("scwin").setReturnValue("[setDisabled(false) - native] select.disabled 속성 = year:'" + yearDisabledAttr + "', month:'" + monthDisabledAttr + "'");
    } else {
        let yearSb = target1.getChild(target1.id + "_selectbox_year");
        let monthSb = target1.getChild(target1.id + "_selectbox_month");
        let yearSbDisabled = yearSb ? yearSb.options.disabled : '없음';
        let monthSbDisabled = monthSb ? monthSb.options.disabled : '없음';
        wf_body_bottom.getObj("scwin").setReturnValue("[setDisabled(false) - component] SelectBox.options.disabled = year:" + yearSbDisabled + ", month:" + monthSbDisabled);
    }
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getAppliedRenderType();
    }, 100);
}
